// The app talks to one of two clients.
//
//  demo  — everything runs in the visitor's browser against the library shipped
//          in web/demo/ (generated by tools/make_demo_data.py from the real
//          sample agreements). Nothing leaves the page.
//  live  — the ordinary FastAPI backend, when the build was given its URL
//          (LEGAL_AI_API_BASE_URL). Same method names, same response shapes, so
//          every page below is written once.

import { buildIndex, search, composeAnswer } from "./engine/retrieval.js";
import { extractLegalEntities, suggestFollowUps } from "./engine/insights.js";

const DEMO_FILES = ["library", "analytics", "audit", "users", "integrations", "questions"];

async function loadDemoData(base) {
  const entries = await Promise.all(DEMO_FILES.map(async (name) => {
    const response = await fetch(`${base}demo/${name}.json`, { cache: "no-cache" });
    if (!response.ok) throw new Error(`Could not load demo/${name}.json (HTTP ${response.status})`);
    return [name, await response.json()];
  }));
  return Object.fromEntries(entries);
}

const DEMO_ACCOUNTS = {
  admin: { password: "admin123", role: "admin", email: "admin@fernwoodlegal.example" },
  "j.ellis": { password: "demo1234", role: "lawyer", email: "j.ellis@fernwoodlegal.example" },
};

function nowIso() { return new Date().toISOString().slice(0, 19); }

function sleep(ms) { return new Promise((resolve) => setTimeout(resolve, ms)); }

/** Browser-only client: the demo everyone sees at yappertech.com/legal-ai-demo. */
class DemoClient {
  constructor(data) {
    this.mode = "demo";
    this.data = data;
    this.documents = data.library.documents.map((document) => ({ ...document }));
    this.passages = data.library.passages.map((passage) => ({ ...passage }));
    this.index = buildIndex(this.searchable());
    this.audit = data.audit.events.map((event) => ({ ...event }));
    this.users = data.users.users.map((user) => ({ ...user }));
    this.deliveries = data.integrations.notifications.recent_deliveries.map((d) => ({ ...d }));
    this.inboxRecent = data.integrations.inbox.recent.map((row) => ({ ...row }));
    this.queriesAsked = 0;
  }

  searchable() { return searchablePassages(this.documents, this.passages); }

  reindex() { this.index = buildIndex(this.searchable()); }

  record(action, status, username, resource = "", details = {}) {
    const previous = this.audit[0];
    this.audit.unshift({
      id: (previous ? previous.id : 0) + 1,
      timestamp: nowIso(),
      action, status, username, resource, details,
      ip_address: "127.0.0.1",
      hash: "demo-session-event", previous_hash: previous ? previous.hash : "",
    });
  }

  async login(username, password) {
    await sleep(220);
    const account = DEMO_ACCOUNTS[username];
    if (!account || account.password !== password) {
      this.record("auth.login", "failure", username, "", { reason: "bad credentials" });
      const error = new Error("Incorrect username or password");
      error.status = 401;
      throw error;
    }
    const profile = this.users.find((user) => user.username === username);
    this.record("auth.login", "success", username);
    return {
      access_token: `demo.${btoa(username)}.session`,
      user: {
        username,
        role: account.role,
        email: account.email,
        must_change_password: false,
        previous_login: profile ? profile.last_login : null,
      },
    };
  }

  async health() {
    return {
      status: "healthy", version: "1.0.0", timestamp: new Date().toISOString(),
      services: { api: "healthy", chromadb: "healthy", model: "not_configured" },
    };
  }

  async listDocuments() {
    const documents = [...this.documents].sort((a, b) => (a.upload_date < b.upload_date ? 1 : -1));
    return {
      documents,
      total: documents.length,
      total_chunks: this.passages.length,
    };
  }

  async documentStats() {
    return {
      document_count: this.documents.length,
      chunk_count: this.passages.length,
      name: "legal_documents",
      status: "healthy",
    };
  }

  async deleteDocument(documentId) {
    const document = this.documents.find((candidate) => candidate.id === documentId);
    this.documents = this.documents.filter((candidate) => candidate.id !== documentId);
    this.passages = this.passages.filter((passage) => passage.document_id !== documentId);
    this.reindex();
    if (document) {
      this.record("document.delete", "success", this.username, document.filename,
        { passages: document.chunk_count });
    }
    return { success: true, message: `Document ${documentId} deleted` };
  }

  /**
   * Index a document the visitor dropped in. Plain text is genuinely parsed,
   * split clause by clause and made searchable; binary formats need the server's
   * parsers (and Tesseract for scans), which a static page does not have.
   */
  async uploadDocument({ text, filename, title, category, contentType }) {
    const started = performance.now();
    await sleep(420);
    if (text === null) {
      const error = new Error(
        "This browser-only demo reads plain text (.txt). PDF, DOCX and scanned images are parsed " +
        "server-side in the real product — including OCR for scans — which a static page cannot do.");
      error.status = 415;
      throw error;
    }

    const documentId = `demo-${Date.now().toString(36)}`;
    const chunks = splitIntoClauses(text);
    chunks.forEach((chunk, index) => {
      this.passages.push({
        id: `${documentId}-${String(index).padStart(4, "0")}`,
        document_id: documentId,
        chunk_index: index,
        section: sectionTitle(chunk),
        text: chunk,
      });
    });
    this.reindex();

    const document = {
      id: documentId,
      filename,
      source: title || filename,
      category,
      document_type: detectType(text),
      page_count: 1,
      word_count: text.split(/\s+/).filter(Boolean).length,
      char_count: text.length,
      chunk_count: chunks.length,
      uploaded_by: this.username || "admin",
      upload_date: nowIso(),
      content_type: contentType || "text/plain",
      file_size: new Blob([text]).size,
      ocr: false,
      via_inbox: false,
      added_in_session: true,
    };
    this.documents.push(document);
    this.record("document.upload", "success", this.username, filename,
      { passages: chunks.length, category });

    return {
      success: true,
      message: "Document processed",
      document_id: documentId,
      chunks_processed: chunks.length,
      processing_time: (performance.now() - started) / 1000,
    };
  }

  /** Retrieve, cite and answer — live, against whatever is in the library now. */
  async query(question, numDocuments = 5) {
    const started = performance.now();
    await sleep(260);
    const hits = search(this.index, question, numDocuments);
    const byId = new Map(this.documents.map((document) => [document.id, document]));

    const sources = hits.map((hit) => {
      const document = byId.get(hit.passage.document_id) || {};
      return {
        document_id: hit.passage.document_id,
        content: hit.passage.text,
        similarity_score: hit.similarity,
        chunk_index: hit.passage.chunk_index,
        metadata: {
          source: document.source || "Unknown",
          category: document.category || "general",
          filename: document.filename,
          section: hit.passage.section,
        },
      };
    });

    const { answer, citations, mode } = composeAnswer(question, hits);
    const citedText = hits
      .filter((_, index) => citations.includes(index + 1))
      .map((hit) => hit.passage.text)
      .join("\n");
    const types = [...new Set(sources.map((source) =>
      (byId.get(source.document_id) || {}).document_type).filter(Boolean))];

    this.queriesAsked += 1;
    this.record("query.ask", "success", this.username, "", {
      passages: sources.length,
      top_similarity: sources.length ? sources[0].similarity_score : 0,
      question: question.slice(0, 80),
    });

    return {
      answer,
      sources,
      citations,
      mode,
      query: question,
      confidence_score: sources.length ? sources[0].similarity_score : 0,
      processing_time: (performance.now() - started) / 1000,
      legal_entities: extractLegalEntities(citedText || (hits[0] ? hits[0].passage.text : "")),
      query_suggestions: suggestFollowUps(question, types),
    };
  }

  async analytics(kind) {
    const usage = structuredClone(this.data.analytics.usage);
    // Keep the dashboard honest about what the visitor has done in this session.
    usage.query_analytics.total_queries += this.queriesAsked;
    usage.document_analytics.total_documents = this.documents.length;
    usage.document_analytics.library_documents = this.documents.length;
    usage.document_analytics.library_chunks = this.passages.length;
    usage.document_analytics.total_chunks = this.passages.length;
    usage.document_analytics.avg_chunks_per_doc =
      Math.round((this.passages.length / Math.max(1, this.documents.length)) * 10) / 10;
    if (this.queriesAsked) {
      const today = new Date().toISOString().slice(0, 10);
      const row = usage.daily_trends.find((entry) => entry.date === today);
      if (row) row.queries += this.queriesAsked;
      else usage.daily_trends.push({ date: today, queries: this.queriesAsked, documents: 0 });
    }

    if (kind === "usage") return { data: usage };
    if (kind === "performance") return { data: structuredClone(this.data.analytics.performance) };
    if (kind === "activity") return { data: structuredClone(this.data.analytics.activity) };
    if (kind === "similarity") return { data: structuredClone(this.data.analytics.similarity) };
    throw new Error(`Unknown analytics section: ${kind}`);
  }

  async report() {
    const usage = (await this.analytics("usage")).data;
    const performance_ = (await this.analytics("performance")).data;
    const activity = (await this.analytics("activity")).data;
    this.record("analytics.export", "success", this.username, "analytics_report.json");
    return {
      generated_at: new Date().toISOString(),
      report_type: "comprehensive",
      report_period: "Last 30 days",
      usage_analytics: usage,
      performance_analytics: performance_,
      user_activity: activity,
      document_library: { documents: this.documents.length, passages: this.passages.length },
    };
  }

  async auditSummary() {
    const by_action = {};
    const by_status = {};
    for (const event of this.audit) {
      by_action[event.action] = (by_action[event.action] || 0) + 1;
      by_status[event.status] = (by_status[event.status] || 0) + 1;
    }
    return { by_action, by_status, total: this.audit.length };
  }

  async auditLogs({ username, action, status, limit = 500 } = {}) {
    let events = this.audit;
    if (username) events = events.filter((event) => (event.username || "").includes(username));
    if (action && action !== "All") {
      events = events.filter((event) => event.action.startsWith(action.replace(/\.$/, "")));
    }
    if (status && status !== "All") events = events.filter((event) => event.status === status);
    return { events: events.slice(0, limit), total: events.length };
  }

  async auditVerify() {
    await sleep(320);
    this.record("audit.verify", "success", this.username, "", { checked: this.audit.length });
    return { valid: true, checked: this.audit.length };
  }

  async listUsers() { return { users: this.users.map((user) => ({ ...user })) }; }

  async createUser({ username, email, role, must_change_password }) {
    if (this.users.some((user) => user.username === username)) {
      const error = new Error(`User ${username} already exists`);
      error.status = 400;
      throw error;
    }
    this.users.push({
      username, email: email || "", role,
      is_active: true, must_change_password: Boolean(must_change_password),
      last_login: null, created_at: nowIso(),
    });
    this.record("user.create", "success", this.username, username, { role });
    return { success: true, message: `Created ${username}` };
  }

  async updateUser(username, changes) {
    const user = this.users.find((candidate) => candidate.username === username);
    if (!user) throw new Error(`No such user: ${username}`);
    Object.assign(user, changes);
    this.record("user.update", "success", this.username, username, changes);
    return { success: true, message: `Updated ${username}. Their other sessions were signed out.` };
  }

  async resetPassword(username) {
    this.record("user.password_reset", "success", this.username, username);
    return { success: true, message: `Temporary password set for ${username}. They must replace it at next sign-in.` };
  }

  async changePassword() {
    this.record("auth.password_change", "success", this.username);
    return { access_token: `demo.${btoa(this.username || "admin")}.session` };
  }

  async integrationsStatus() {
    const inbox = structuredClone(this.data.integrations.inbox);
    const notifications = structuredClone(this.data.integrations.notifications);
    inbox.recent = this.inboxRecent;
    inbox.last_scan = nowIso();
    notifications.recent_deliveries = this.deliveries;
    return { inbox, notifications };
  }

  async scanInbox() {
    await sleep(500);
    return { counts: { processed: 0, failed: 0, waiting: 0 } };
  }

  async testIntegration() {
    await sleep(450);
    const timestamp = nowIso();
    const deliveries = [
      { target: "n8n", ok: true, status_code: 200 },
      { target: "slack", ok: true, status_code: 200 },
    ];
    for (const delivery of deliveries) {
      this.deliveries.unshift({ timestamp, event: "integration.test", target: delivery.target, ok: true, attempts: 1 });
    }
    this.record("integration.test", "success", this.username, "n8n", { status_code: 200 });
    return { deliveries };
  }
}

/** Thin wrapper over the real FastAPI backend, used when the build sets its URL. */
class LiveClient {
  constructor(baseUrl) {
    this.mode = "live";
    this.baseUrl = baseUrl.replace(/\/+$/, "");
    this.token = null;
  }

  async request(path, { method = "GET", json, form, raw } = {}) {
    const headers = {};
    if (this.token) headers.Authorization = `Bearer ${this.token}`;
    if (json) headers["Content-Type"] = "application/json";
    const response = await fetch(`${this.baseUrl}${path}`, {
      method, headers, body: json ? JSON.stringify(json) : form,
    });
    if (!response.ok) {
      let detail = `HTTP ${response.status}`;
      try { detail = (await response.json()).detail || detail; } catch { /* non-JSON error body */ }
      const error = new Error(detail);
      error.status = response.status;
      throw error;
    }
    return raw ? response : response.json();
  }

  async login(username, password) {
    const result = await this.request("/auth/login", { method: "POST", json: { username, password } });
    this.token = result.access_token;
    return result;
  }

  health() { return this.request("/health"); }
  listDocuments() { return this.request("/documents"); }
  documentStats() { return this.request("/documents/stats"); }
  deleteDocument(id) { return this.request(`/documents/${id}`, { method: "DELETE" }); }

  uploadDocument({ file, title, category }) {
    const form = new FormData();
    form.append("file", file);
    form.append("title", title);
    form.append("category", category);
    return this.request("/documents/upload", { method: "POST", form });
  }

  query(question, numDocuments = 5) {
    return this.request("/query", { method: "POST", json: { question, num_documents: numDocuments } });
  }

  analytics(kind) { return this.request(`/analytics/${kind}`); }
  report() { return this.request("/analytics/report?format=json"); }
  auditSummary() { return this.request("/audit/summary?days=30"); }

  auditLogs(params = {}) {
    const query = new URLSearchParams({ limit: String(params.limit || 500), days: String(params.days || 30) });
    if (params.username) query.set("username", params.username);
    if (params.action && params.action !== "All") query.set("action", params.action);
    if (params.status && params.status !== "All") query.set("status_filter", params.status);
    return this.request(`/audit/logs?${query}`);
  }

  auditVerify() { return this.request("/audit/verify"); }
  listUsers() { return this.request("/users"); }
  createUser(body) { return this.request("/auth/register", { method: "POST", json: body }); }
  updateUser(username, changes) { return this.request(`/users/${username}`, { method: "PATCH", json: changes }); }

  resetPassword(username, newPassword) {
    return this.request(`/users/${username}/reset-password`, { method: "POST", json: { new_password: newPassword } });
  }

  changePassword(current, next) {
    return this.request("/auth/change-password",
      { method: "POST", json: { current_password: current, new_password: next } });
  }

  integrationsStatus() { return this.request("/integrations/status"); }
  scanInbox() { return this.request("/integrations/inbox/scan", { method: "POST" }); }
  testIntegration() { return this.request("/integrations/test", { method: "POST" }); }
}

/**
 * Passages carrying the words that give them context — the document's title,
 * category and type, plus the clause heading — so a question that names a
 * document ("the services agreement", "the NDA") reaches that document's
 * clauses and not another's. Every agreement has a governing-law clause; the
 * title is what tells them apart. Only `text` is ever displayed.
 */
export function searchablePassages(documents, passages) {
  const byId = new Map(documents.map((document) => [document.id, document]));
  return passages.map((passage) => {
    const document = byId.get(passage.document_id) || {};
    const contextText = [document.source, document.category, document.document_type, passage.section]
      .filter(Boolean).join(" ").replace(/_/g, " ");
    return { ...passage, contextText, searchText: `${contextText} ${passage.text}` };
  });
}

/** Split text clause by clause, the way rag/embedder.py does for these documents. */
export function splitIntoClauses(text) {
  const clean = text.replace(/[ \t\r\f\v]+/g, " ").replace(/\n\s*\n+/g, "\n\n").trim();
  const pattern = /\n\s*(?:Section|Article|Chapter|Part)\s+\d+/g;
  const positions = [];
  let match;
  while ((match = pattern.exec(clean)) !== null) positions.push(match.index);

  if (positions.length < 2) {
    // No clause structure: fall back to paragraphs, then to the whole text.
    const paragraphs = clean.split(/\n{2,}/).map((part) => part.trim()).filter(Boolean);
    return paragraphs.length ? paragraphs : [clean];
  }

  const sections = [];
  const preamble = clean.slice(0, positions[0]).trim();
  if (preamble) sections.push(preamble);
  positions.forEach((start, index) => {
    const end = index + 1 < positions.length ? positions[index + 1] : clean.length;
    const body = clean.slice(start, end).trim();
    if (body) sections.push(body);
  });
  return sections;
}

export function sectionTitle(text) {
  const full = text.match(/^\s*(Section|Article)\s+(\d+)\.\s*([A-Z][A-Za-z ,'&/-]{2,60}?)\./);
  if (full) return `${full[1]} ${full[2]}. ${full[3].trim()}`;
  const short = text.match(/^\s*(Section|Article)\s+(\d+)/);
  return short ? `${short[1]} ${short[2]}` : "";
}

function detectType(text) {
  const lowered = text.toLowerCase();
  if (lowered.includes("non-disclosure") || lowered.includes("confidential information")) return "nda";
  if (lowered.includes("lease") && lowered.includes("tenant")) return "lease";
  if (lowered.includes("employee") && lowered.includes("employment")) return "employment";
  if (lowered.includes("license") && lowered.includes("licensee")) return "license";
  return "contract";
}

/** Pick the client this build should use. */
export async function createClient(config) {
  if (config.apiBaseUrl) return new LiveClient(config.apiBaseUrl);
  const data = await loadDemoData(config.basePath);
  return new DemoClient(data);
}
